(function lockSelection() {
  if (typeof document === "undefined" || document.getElementById("cherry-noselect")) return;
  const css = document.createElement("style");
  css.id = "cherry-noselect";
  css.textContent =
    "*{-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none;" +
    "-webkit-touch-callout:none;-webkit-tap-highlight-color:transparent;}" +
    /* ✍️ ช่องพิมพ์ต้องเลือก/แก้/วางข้อความได้ตามปกติ */
    "input,textarea,select,[contenteditable=\"true\"]{-webkit-user-select:text;-moz-user-select:text;" +
    "-ms-user-select:text;user-select:text;-webkit-touch-callout:default;}" +
    "html,body{touch-action:manipulation;-webkit-text-size-adjust:100%;overscroll-behavior:none;}" +
    "img{-webkit-user-drag:none;}";
  (document.head || document.documentElement).appendChild(css);
  const typable = (el) => !!(el && el.closest && el.closest('input,textarea,select,[contenteditable="true"]'));
  document.addEventListener("contextmenu", (e) => { if (!typable(e.target)) e.preventDefault(); });   // กดค้าง = ไม่เด้งเมนูก็อปปี้
  document.addEventListener("selectstart", (e) => { if (!typable(e.target)) e.preventDefault(); });   // กดย้ำ = ไม่คลุมข้อความ
})();
