// ⚖️ ตัวคูณความยากประจำแดน — ด่านฝึกมือกำหนด hpMul/atkMul ไว้ต่ำกว่า 1 (แดนอื่นไม่ระบุ = 1 เท่าเดิม)
const biomeHpMul = (b) => (b && b.hpMul != null ? b.hpMul : 1);
const biomeAtkMul = (b) => (b && b.atkMul != null ? b.atkMul : 1);
const rollRarity = (boss, lv, eliteBoss) => {
  const L = Math.max(1, lv || 1);
  const r = Math.random();
  if (boss) {
    if (eliteBoss || L >= 150)  return r < 0.060 ? "dragon" : r < 0.240 ? "secret" : r < 0.70 ? "epic" : "rare";
    if (L >= 60)                return r < 0.015 ? "dragon" : r < 0.120 ? "secret" : r < 0.58 ? "epic" : "rare";
    if (L >= 25)                return r < 0.040 ? "secret" : r < 0.42 ? "epic" : r < 0.85 ? "rare" : "common";
    return r < 0.10 ? "epic" : r < 0.62 ? "rare" : "common";        // บอส/ตัวหายากเลเวลต้น ๆ ยังไม่ให้ของระดับสูง
  }
  if (L >= 120) return r < 0.004 ? "secret" : r < 0.070 ? "epic" : r < 0.34 ? "rare" : "common";
  if (L >= 60)  return r < 0.025 ? "epic"   : r < 0.28 ? "rare" : "common";
  if (L >= 25)  return r < 0.008 ? "epic"   : r < 0.20 ? "rare" : "common";
  return r < 0.10 ? "rare" : "common";
};
