          if (idx >= pos.count) continue;
          const px = pos.getX(idx), py = pos.getY(idx), pz = pos.getZ(idx);
          pos.setX(idx, center.x + (px - center.x) * taper);
          pos.setY(idx, center.y + (py - center.y) * taper);
          pos.setZ(idx, center.z + (pz - center.z) * taper);
