      const curls = [[0, 0.52, 0.28, 0.26], [-0.3, 0.48, 0.3, 0.24], [0.3, 0.48, 0.3, 0.24], [-0.5, 0.3, 0.18, 0.24], [0.5, 0.3, 0.18, 0.24], [-0.55, 0.1, -0.1, 0.22], [0.55, 0.1, -0.1, 0.22], [-0.36, 0.42, -0.34, 0.26], [0.36, 0.42, -0.34, 0.26], [0, 0.5, -0.4, 0.28], [-0.16, 0.58, 0.42, 0.2], [0.18, 0.58, 0.42, 0.2], [-0.44, 0.34, 0.4, 0.18], [0.44, 0.34, 0.4, 0.18], [0, 0.34, 0.56, 0.17]];
