      const band = new THREE.Mesh(new THREE.TorusGeometry(0.54, 0.035, 8, 26, 2.4), kGold); band.position.set(0, 0.34, 0.2); band.rotation.set(1.42, 0, 0); crown.add(band);
      const gemFrame = new THREE.Mesh(new THREE.OctahedronGeometry(0.12, 0), kGold); gemFrame.scale.set(0.85, 1.25, 0.4); gemFrame.position.set(0, 0.46, 0.6); crown.add(gemFrame);
      const crownGem = new THREE.Mesh(new THREE.OctahedronGeometry(0.095, 0), kCry); crownGem.scale.set(0.85, 1.3, 0.5); crownGem.position.set(0, 0.46, 0.65); crown.add(crownGem);
