        for (let k = 0; k < 3; k++) { const w = new THREE.Mesh(new THREE.ConeGeometry(0.05 - k * 0.008, 0.34 - k * 0.06, 4), k % 2 ? kGoldE : kGold); w.position.set(sx * (0.52 + k * 0.09), 0.36 + k * 0.09, 0.34 - k * 0.05); w.rotation.set(0.2, 0, sx * (1.9 - k * 0.22)); w.scale.z = 0.4; crown.add(w); }
