      const under = new THREE.Mesh(new THREE.LatheGeometry([[0.33, 1.26], [0.35, 1.46], [0.36, 1.66], [0.34, 1.84]].map(([r, y]) => new THREE.Vector2(r, y)), 24), kBlueD); under.scale.set(1.04, 1, 0.96); kOutfit.add(under);
