      const starBack = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.1, 0.03, 5), kGoldE); starBack.position.set(0, 1.82, 0.38); starBack.rotation.x = Math.PI / 2; kOutfit.add(starBack);
      const star = new THREE.Mesh(new THREE.OctahedronGeometry(0.08, 0), kCry); star.scale.set(1, 1.3, 0.4); star.position.set(0, 1.82, 0.42); kOutfit.add(star);
      // glowing blue lightning runes on the torso
      for (const [rx, ry] of [[-0.24, 1.62], [0.24, 1.62], [0, 1.5]]) { const rune = new THREE.Mesh(new THREE.ConeGeometry(0.022, 0.12, 4), kBolt); rune.position.set(rx, ry, 0.36); rune.rotation.z = rx * 2; kOutfit.add(rune); }
      char.add(kOutfit); G._kaiOutfit = kOutfit;

      // ===== rounded white-gold pauldrons + blue gems =====
      const kWings = [];
      const mkPauld = sx => { const grp = new THREE.Group(); const dome = new THREE.Mesh(new THREE.SphereGeometry(0.17, 14, 10, 0, Math.PI * 2, 0, Math.PI * 0.6), kWhite); grp.add(dome); const rim = new THREE.Mesh(new THREE.TorusGeometry(0.16, 0.02, 6, 18), kGold); rim.rotation.x = Math.PI / 2; grp.add(rim); const plate2 = new THREE.Mesh(new THREE.SphereGeometry(0.14, 12, 8, 0, Math.PI * 2, 0, Math.PI * 0.5), kWhiteD); plate2.position.y = -0.07; grp.add(plate2); const pg = new THREE.Mesh(new THREE.OctahedronGeometry(0.05, 0), kCry); pg.position.set(0, 0.1, 0.08); grp.add(pg); const spike = new THREE.Mesh(new THREE.ConeGeometry(0.035, 0.16, 4), kGoldE); spike.position.set(sx * 0.12, 0.14, 0); spike.rotation.z = sx * 1.0; grp.add(spike); grp.position.set(sx * 0.52, 1.96, -0.02); grp.rotation.z = sx * 0.16; char.add(grp); kWings.push(grp); return grp; };
      mkPauld(-1); mkPauld(1);

