      const sash = new THREE.Mesh(new THREE.CylinderGeometry(0.37, 0.385, 0.13, 22, 1, true), kBlue); sash.position.y = 1.28; sash.scale.set(1.05, 1, 0.96); kOutfit.add(sash);
      for (const sy of [1.345, 1.215]) { const tr = new THREE.Mesh(new THREE.TorusGeometry(0.385, 0.012, 6, 26), kGold); tr.position.y = sy; tr.rotation.x = Math.PI / 2; tr.scale.set(1.05, 0.96, 1); kOutfit.add(tr); }
      const buckleF = new THREE.Mesh(new THREE.OctahedronGeometry(0.085, 0), kGold); buckleF.scale.set(1, 1.15, 0.4); buckleF.position.set(0, 1.28, 0.38); kOutfit.add(buckleF);
      const buckle = new THREE.Mesh(new THREE.OctahedronGeometry(0.06, 0), kCry); buckle.scale.set(1, 1.2, 0.5); buckle.position.set(0, 1.28, 0.41); kOutfit.add(buckle);
      for (const sx of [-1, 1]) { const bg = new THREE.Mesh(new THREE.OctahedronGeometry(0.035, 0), kCry); bg.position.set(sx * 0.2, 1.28, 0.35); kOutfit.add(bg); }

