      const skirt = new THREE.Mesh(new THREE.CylinderGeometry(0.38, 0.48, 0.32, 24, 1, true), kWhite); skirt.position.y = 1.06; kOutfit.add(skirt);
      const skirtTrim = new THREE.Mesh(new THREE.TorusGeometry(0.48, 0.016, 6, 26), kGold); skirtTrim.position.y = 0.9; skirtTrim.rotation.x = Math.PI / 2; kOutfit.add(skirtTrim);
      for (let i = 0; i < 5; i++) { const a = -Math.PI / 2 + (i - 2) * 0.62; const plate = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.3, 0.035), kWhite); plate.position.set(Math.sin(a) * 0.42, 1.02, Math.cos(a) * 0.42); plate.rotation.order = "YXZ"; plate.rotation.y = a; plate.rotation.x = 0.22; kOutfit.add(plate); const ptrim = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.045, 0.04), kGold); ptrim.position.set(Math.sin(a) * 0.46, 0.9, Math.cos(a) * 0.46); ptrim.rotation.order = "YXZ"; ptrim.rotation.y = a; ptrim.rotation.x = 0.22; kOutfit.add(ptrim); }
      for (const [ey, ex] of [[1.06, 0.02], [0.98, -0.02]]) { const em = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.1, 0.02), kBolt); em.position.set(ex, ey, 0.47); em.rotation.z = ex > 0 ? -0.5 : 0.5; kOutfit.add(em); }

