        b.position.set(sx * 0.2, 1.72, -0.34); b.rotation.order = "ZXY"; b.rotation.z = sx * angZ; b.rotation.x = -0.42 - i * 0.05; b.userData.bz = sx * angZ;
        kCape.add(b); kWingBlades.push(b);
