      if (kind === "scale") { // เกล็ดถักโค้งเรียงสลับแถว
        for (let ry = 0; ry < 8; ry++) for (let rx = 0; rx < 8; rx++) { const ox = (ry % 2) * 4; cx.beginPath(); cx.arc(rx * 8 + 4 + ox, ry * 8 + 4, 3.4, 0, Math.PI); cx.strokeStyle = "rgba(0,0,0,0.3)"; cx.lineWidth = 1.5; cx.stroke(); }
      } else { // ลายทอผ้าแนวขวาง-ตั้ง
        for (let i = 0; i < 64; i += 3) { cx.fillStyle = "rgba(0,0,0,0.16)"; cx.fillRect(0, i, 64, 1); cx.fillStyle = "rgba(255,255,255,0.12)"; cx.fillRect(i, 0, 1, 64); }
      }
