      const suit = new THREE.Mesh(new THREE.LatheGeometry([[0.415, 1.3], [0.418, 1.44], [0.42, 1.58], [0.422, 1.72], [0.412, 1.85], [0.35, 1.95], [0.22, 2.04]].map(([r, y]) => new THREE.Vector2(r, y)), 28), knitMat);
