      snout.position.set(0, 0.42, 0.5);
      snout.scale.set(1, 1, 0.7);
      g.add(snout);
      const upperJaw = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.12, 0.36), scaleM);
      upperJaw.position.set(0, 0.34, 0.5);
