          spike.rotation.z = -a * 0.6; g.add(spike);
          const gem = new THREE.Mesh(new THREE.OctahedronGeometry(0.03), lightM);
          gem.position.set(Math.sin(a) * 0.46, 0.56, Math.cos(a) * 0.46 * 0.7 + 0.12); g.add(gem);
