      for (const sy of [-0.12, -0.3]) { const band = new THREE.Mesh(new THREE.TorusGeometry(0.132, 0.012, 6, 18), goldMat); band.position.y = sy; band.rotation.x = Math.PI / 2; grp.add(band); }
