    const amazonBush = [];  // 🌿 เฟิร์น/พุ่มเตี้ย — ซ่อนเมื่อมาขวางแนวกล้อง→ตัวละคร
    // 🟢 green wet ground overlay (darker jungle floor over the base ground)
    const jungleFloor = new THREE.Mesh(new THREE.CircleGeometry(FIELD_R + 4, 48), new THREE.MeshStandardMaterial({ color: 0x244a28, roughness: 1 }));
    jungleFloor.rotation.x = -Math.PI / 2; jungleFloor.position.y = 0.015; jungleFloor.userData.noHide = true; amazonDecor.add(jungleFloor);
    // 🏞️ Amazon river — a wide winding water band crossing the map (murky green-brown)
    const riverMat = new THREE.MeshStandardMaterial({ color: 0x2a5a52, roughness: 0.3, metalness: 0.1, transparent: true, opacity: 0.9 });
    const river = new THREE.Mesh(new THREE.PlaneGeometry(9, 130, 4, 40), riverMat);
    (G._waterSurf = G._waterSurf || []).push({ m: river, base: river.geometry.attributes.position.array.slice(), amp: 0.07, hz: 1.2, k: 0.8 });   // 🌊 กระแสน้ำไหลเป็นลอน
    river.rotation.x = -Math.PI / 2; river.rotation.z = 0.5; river.position.set(4, 0.05, -2); river.userData.noHide = true; amazonDecor.add(river);
    const riverBank = new THREE.Mesh(new THREE.PlaneGeometry(11, 130), new THREE.MeshStandardMaterial({ color: 0x3a3a24, roughness: 1, transparent: true, opacity: 0.6 }));
    riverBank.rotation.x = -Math.PI / 2; riverBank.rotation.z = 0.5; riverBank.position.set(4, 0.035, -2); riverBank.userData.noHide = true; amazonDecor.add(riverBank);
    G.amazonRiver = river;
    // 🌳 giant canopy tree — tall buttressed trunk + layered green canopy
    const barkMat = new THREE.MeshStandardMaterial({ color: 0x5a4632, roughness: 0.95 });
    const barkD = new THREE.MeshStandardMaterial({ color: 0x40331f, roughness: 0.98 });
    const canopy1 = new THREE.MeshStandardMaterial({ color: 0x2f6b34, roughness: 0.85, flatShading: true });
    const canopy2 = new THREE.MeshStandardMaterial({ color: 0x256030, roughness: 0.85, flatShading: true });
    const canopy3 = new THREE.MeshStandardMaterial({ color: 0x3a7a3e, roughness: 0.85, flatShading: true });
    const makeBigTree = (x, z) => {
      if (inKeepOut(x, z)) return;
      const g = new THREE.Group();
      const h = rnd(7, 11);
      const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.62, h, 12), barkMat);
      trunk.position.y = h / 2; trunk.castShadow = true; g.add(trunk);
      // buttress roots at the base
      for (let k = 0; k < 5; k++) { const a = (k / 5) * Math.PI * 2; const root = new THREE.Mesh(new THREE.ConeGeometry(0.22, 1.4, 5), barkD); root.position.set(Math.cos(a) * 0.5, 0.6, Math.sin(a) * 0.5); root.rotation.x = Math.PI; root.scale.set(1, 1, 0.5); root.rotation.y = -a; g.add(root); }
      // hanging vines
      for (let k = 0; k < 3; k++) { const a = Math.random() * Math.PI * 2; const vine = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, rnd(1.4, 2.6), 5), canopy2); vine.position.set(Math.cos(a) * 1.2, h - rnd(1, 2.5), Math.sin(a) * 1.2); g.add(vine); }
      // layered canopy (big overlapping blobs) high up
      const cy = h + 0.2;
      for (let k = 0; k < 7; k++) { const a = (k / 7) * Math.PI * 2; const r = 1.7 + (k % 3) * 0.5; const blob = new THREE.Mesh(new THREE.SphereGeometry(rnd(1.5, 2.4), 12, 10), [canopy1, canopy2, canopy3][k % 3]); blob.position.set(Math.cos(a) * r, cy + rnd(-0.6, 0.9), Math.sin(a) * r); blob.castShadow = true; g.add(blob); }
      const crown = new THREE.Mesh(new THREE.SphereGeometry(2.4, 14, 12), canopy1); crown.position.y = cy + 1; crown.scale.set(1, 0.8, 1); g.add(crown);
      g.position.set(x, 0, z); g.scale.setScalar(rnd(0.85, 1.2));
      amazonDecor.add(g); amazonColliders.push({ x, z, r: 0.8 }); amazonTrees.push(g);
    };
    // 🌿 giant fern — arching fronds from a low center
    const fernMat = new THREE.MeshStandardMaterial({ color: 0x3c8a3e, roughness: 0.8, side: THREE.DoubleSide, flatShading: true });
    const fernMatD = new THREE.MeshStandardMaterial({ color: 0x2c6e30, roughness: 0.85, side: THREE.DoubleSide, flatShading: true });
    const makeFern = (x, z) => {
      if (inKeepOut(x, z)) return;
      const g = new THREE.Group();
      const n = 7 + (Math.random() * 3 | 0);
      for (let k = 0; k < n; k++) {
        const a = (k / n) * Math.PI * 2;
        const piv = new THREE.Group(); piv.rotation.y = a; piv.rotation.z = -0.5 - Math.random() * 0.2;
        const frond = new THREE.Mesh(new THREE.ConeGeometry(0.22, rnd(1.4, 2.1), 4), k % 2 ? fernMat : fernMatD);
        frond.scale.set(1, 1, 0.16); frond.rotation.z = -Math.PI / 2; frond.position.x = rnd(0.8, 1.1); frond.castShadow = true;
        piv.add(frond); g.add(piv);
      }
      g.position.set(x, 0.1, z); g.scale.setScalar(rnd(0.9, 1.4));
      amazonDecor.add(g); amazonColliders.push({ x, z, r: 0.5 }); amazonBush.push(g); // 🌿 เฟิร์นสูงเกือบเท่าตัวละคร — ต้องหลบกล้องด้วย
    };
    // 🌱 grass tufts on the green floor
    const grassMat = new THREE.MeshStandardMaterial({ color: 0x3f8a40, roughness: 0.9, side: THREE.DoubleSide });
    const makeGrass = (x, z) => {
      if (inKeepOut(x, z)) return;
      const g = new THREE.Group();
      for (let k = 0; k < 5; k++) { const bl = new THREE.Mesh(new THREE.ConeGeometry(0.05, rnd(0.3, 0.6), 3), grassMat); bl.position.set(rnd(-0.15, 0.15), 0.2, rnd(-0.15, 0.15)); bl.rotation.z = rnd(-0.3, 0.3); bl.scale.set(1, 1, 0.4); g.add(bl); }
      g.position.set(x, 0, z); amazonDecor.add(g);
    };
    // 💧 swamp puddles (wetland)
