    G.eventT = 20; // first event comes fairly soon

    // ---------- 🗼 Dungeon gate — rectangular tower doorway ----------
    const portal = new THREE.Group();
    const gateStone = new THREE.MeshStandardMaterial({ color: 0x3a2a5a, roughness: 0.85, metalness: 0.1 });
    const gateTrim = new THREE.MeshStandardMaterial({ color: 0x9a6ad0, emissive: 0x6a2ad0, emissiveIntensity: 0.95, roughness: 0.4, metalness: 0.3 });
    const DW = 1.7, DH = 2.6, TH = 0.28; // 🚪 door width / height / frame thickness (rectangular)
