    for (let k = -1; k <= 1; k++) {
      const cren = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.3, TH), gateStone);
      cren.position.set(k * 0.62, DH + 0.3, 0); portal.add(cren);
    }
    // ✨ glowing rectangular trim just inside the frame
    const trimTop = new THREE.Mesh(new THREE.BoxGeometry(DW - TH, 0.07, 0.07), gateTrim);
    trimTop.position.set(0, DH - TH / 2, TH / 2 + 0.01); portal.add(trimTop);
    const pRing = trimTop; // 🔖 kept for reference compatibility
    for (const sx of [-1, 1]) {
      const tv = new THREE.Mesh(new THREE.BoxGeometry(0.07, DH - TH, 0.07), gateTrim);
      tv.position.set(sx * (DW / 2 - TH / 2), (DH - TH) / 2, TH / 2 + 0.01); portal.add(tv);
    }
