      if (G.herbRespawnAll) { try { G.herbRespawnAll(); } catch (e) {} }   // 🎣 ปั้นบ่อกลับคืนตอนออกจากเมือง
      const r = G._townReturn || { x: -9.5, z: -5.5 };
