          st.pos[i * 6 + 0] = h.top.x; st.pos[i * 6 + 1] = h.top.y; st.pos[i * 6 + 2] = h.top.z;
          st.pos[i * 6 + 3] = h.bot.x; st.pos[i * 6 + 4] = h.bot.y; st.pos[i * 6 + 5] = h.bot.z;
