      G.wbAtkDebuff = 0; G.wbCritDebuff = 0; // 👹 clear the boss aura
      if (G.enemy) { const mm = G.enemy.mesh; if (mm) { burst(mm.position, 0xf5d05a, 2.4); scene.remove(mm); (G._disposeObj3D && G._disposeObj3D(mm)); } G.enemy = null; }
