      const golden = !!wild.userData.golden;
      const shiny = !!wild.userData.shiny;
      const ngMul = (1 + (G.ngPlus || 0) * 0.4) * (shiny ? 1.3 : 1); // 🔄 NG+ + ✨ shiny tougher
