      if (wild.userData.friendStats) {
        const fs = wild.userData.friendStats;
        G.enemy.hp = fs.hp; G.enemy.maxHp = fs.hp;
        G.enemy.atk = fs.atk; G.enemy.name = fs.name;
        G.enemy.friendGhost = true;
      }
      // remove from wild list (battle owns it now)
      const idx = wilds.indexOf(wild);
      if (idx >= 0) wilds.splice(idx, 1);
      if (wild.userData.lbl) wild.userData.lbl.sprite.visible = false; // hide floating tag in battle
      // status effects & battle buffs
      G.est = { burn: 0, frozen: false, poison: 0, bleed: 0, confused: 0, aura: null, defBreak: 0 };
      if (G.auraRingHide) G.auraRingHide();
      {   // 🌦️ อากาศทาธาตุให้ศัตรูตั้งแต่เริ่มสู้ — ฝนตกอยู่ = ศัตรูติดธาตุน้ำ ยิงไฟใส่ทันทีได้ปฏิกิริยาเลย
        const wEl = (G.weather && G.weather.boost) || null;
        if (wEl && Math.random() < 0.55) G.est.aura = { el: wEl, turns: 3 };
      }
      G.pst = { poison: 0, stun: 0, poisonDmg: 0 }; // 🐍💫 สถานะที่มอนสเตอร์ทำใส่ผู้เล่น
      G.comboSeq = []; G.chainMult = 1; setUi((u) => ({ ...u, chainLen: 0, pPoison: 0, pStun: 0, advUltUsed: false })); // ⚔️ reset skill chain + player status
