      // stage positions
      battleCenter.set(char.position.x, 0, char.position.z);
      G.enemyX = worldBoss ? 3.0 : boss ? 2.0 : 1.3; // bosses stand further back (they're huge!) · 👹 world boss far back
      // 🌳 hide EVERYTHING that could block the view of the battle (trees, decor, npc, warp, other monsters)
      G._hiddenScenery = [];
      const hideNear = (obj, radius) => {
        if (!obj || !obj.visible) return;
        const dx = obj.position.x - battleCenter.x, dz = obj.position.z - battleCenter.z;
        if (Math.hypot(dx, dz) < radius) { obj.visible = false; G._hiddenScenery.push(obj); }
      };
      // trees/bushes/rocks — wide radius so nothing sits in front of the fighters
      for (const obj of sceneryObjects) hideNear(obj, 7.5);
      // biome decor pieces (cacti, ice, crystals, lava rocks, sky isles) — hide individual children near the stage
      if (G.biomeDecorGroups) {
        for (const grp of G.biomeDecorGroups) {
          if (grp && grp.visible && grp.children) grp.children.forEach((c) => { if (!(c.userData && c.userData.noHide)) hideNear(c, 7.5); });
        }
      }
      // NPC + warp gate if they're near the stage
      if (G.npc) hideNear(G.npc, 7.5);
      if (G.warpGate) hideNear(G.warpGate, 7.5);
