        g.userData = { kind: "pool", t: 0, dur: dur || 4.5, r, dmg, col: col || 0x7ad04a, next: 0.6, puff: 0, dotKind: dotKind || "poison", onTick, mats };
        scene.add(g); archerFx.push(g);
