          ear.position.set(sx * 0.1, 0.4, 0.5); ear.rotation.z = sx * 0.3; g.add(ear);
          const ey = new THREE.Mesh(new THREE.SphereGeometry(0.05, 8, 6), eye);
          ey.position.set(sx * 0.09, 0.27, 0.69); g.add(ey);
