      toast("🌐 กำลังโหลดกระดานอันดับโลก...");
      const rows = await CN.leaderboard(20);
      if (!rows) { toast("❌ โหลดไม่สำเร็จ ลองใหม่อีกครั้ง"); setUi((u) => ({ ...u, netStatus: CN.status })); return; }
      const myIdx = G.pid ? rows.findIndex((r) => r.pid === G.pid) : -1;
