          const aSilver = new THREE.MeshStandardMaterial({ color: 0xa8b0bc, metalness: 0.92, roughness: 0.22 });
          const aDark = new THREE.MeshStandardMaterial({ color: 0x12151d, metalness: 0.72, roughness: 0.42 });
