      const b = { pid: B.pid, n: B.n, atk: B.atk || 10, def: B.def || 0, crit: B.crit || 0, hp: Math.max(1, B.hp | 0), max: Math.max(1, B.hp | 0) };
      const aFirst = (a.max !== b.max) ? (A.lv || 0) >= (B.lv || 0) : true; // faster/stronger strikes first, ties → challenger
