            const typ = Math.sin(rp * Math.PI * 26) * 0.16 * (1 - Math.min(1, rp / 0.7));
            const btC = rp * 3, biC = Math.floor(btC), bfC = btC - biC;
            const bm2 = smK(Math.min(1, bfC * 2.4));
