            const btA = rp * 5, biA = Math.floor(btA), bfA = btA - biA;
            const hitA = smK(Math.min(1, bfA * 2.6)), sdA = biA % 2 ? -1 : 1;
            const isKnee = biA === 2 || biA === 4;                             // จังหวะ 3 กับ 5 เป็นเข่า
            const rO = sdA < 0 ? hitA : 0, lO = sdA > 0 ? hitA : 0;
