            const btB = rp * 6, biB = Math.floor(btB), bfB = btB - biB;
            const jb = smK(Math.min(1, bfB * 3.2)), sdB = biB % 2 ? -1 : 1;
            const rJ = sdB < 0 ? jb : 0, lJ = sdB > 0 ? jb : 0;
