            const btC = rp * 2, biC = Math.floor(btC), bfC = btC - biC;
            const hk = smK(Math.min(1, bfC * 2.0)), sdC = biC % 2 ? -1 : 1;
            armR.rotation.x = (-1.35 - 0.2 * ce - (sdC < 0 ? 0.5 : 0) * hk) * ease;
