                { const _P = curPath(); if (_P && _P.chillOnHit) { G.enemy.slowed = true; if (Math.random() < (_P.freezeChance || 0)) { G.est.frozen = true; fxMsg += " แช่แข็งดำ 🧊"; } else fxMsg += " เยือกแข็ง ❄️"; } }
