              //                                        → ดาบพลาสมายักษ์ฟันพื้น → คลื่น EMP · เจาะเกราะ + สตัน
              const cyanA = 0x3ad0ff, deepA = 0x1060c0, whiteA = 0xeaf8ff, warnA = 0xff5a3a, plasA = 0x8ae8ff;
