                setUi((u) => ({
                  ...u, col: { ...G.col }, pets: { ...G.pets }, petBox: (G.petBox || []).map((x) => ({ ...x })),
                  msg: petInst ? `🎊 จับ${sp.name} Lv.${petInst.lv} ได้! พรสวรรค์ ${petInst.iv.a + petInst.iv.h + petInst.iv.d} ✨` : `🎊 จับ${sp.name}ได้ แต่กล่องเต็ม (${G.petCap()}) — บันทึกในสมุดภาพ`,
                }));
