          if (wu.halo) wu.halo.rotation.z += 0.02;
          if (wu.orb) { wu.orb.material.emissiveIntensity = 1.1 + Math.sin(t * 3) * 0.45; wu.orb.scale.setScalar(1 + Math.sin(t * 3) * 0.07); }
          break;
