  const isPrompt = (name) => _promptTop === name;
  // 🎯 เดินเข้าใกล้ สายแร่/บ่อน้ำ/กอสมุนไพร → ปุ่มโจมตีกลางจอสลับเป็น ขุด/ตกปลา/เก็บ
  //    (ป้ายกลางหน้าจอของเรื่องนั้นจะถูกซ่อน ไม่ให้มีปุ่มซ้ำสองที่)
